package net.civeira.phylax.features.document.templateversion.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class ContentHtmlVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property content html of template version ")
  void test_content_html_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> ContentHtmlVO.tryFrom(null));
    Assertions.assertEquals("one", ContentHtmlVO.from("one").getContentHtml());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> ContentHtmlVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", ContentHtmlVO.from("one").toString());
  }
}
